CREATE FUNCTION "model_15273b88e4204687"."before"() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $model$DECLARE k bigint; p uuid; live boolean; v uuid; BEGIN
IF TG_OP<>'DELETE' AND (NEW.id IS NULL OR NEW.balance IS NULL OR NEW.active IS NULL OR NEW.region IS NULL) THEN RETURN NEW; END IF;
IF TG_OP='UPDATE' AND NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'primary key mutation'; END IF;
k:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;
SELECT version,present INTO p,live FROM "model_15273b88e4204687"."state" WHERE key=k FOR UPDATE;
IF NOT FOUND THEN RAISE EXCEPTION 'key outside configured domain'; END IF;
IF TG_OP<>'INSERT' AND (NOT live OR p IS DISTINCT FROM OLD.version) THEN RAISE EXCEPTION 'source mismatch'; END IF;
v:=gen_random_uuid();
INSERT INTO "model_15273b88e4204687"."candidates" VALUES(v,k,p,TG_OP,live,TG_OP<>'DELETE',CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('balance',NEW.balance::text,'active',NEW.active,'region',NEW.region) END);
IF TG_OP='DELETE' THEN RETURN OLD; ELSE NEW.version:=v; RETURN NEW; END IF;
END$model$

CREATE FUNCTION "model_15273b88e4204687"."after"() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $model$DECLARE v uuid; c record; n integer; BEGIN
v:=CASE WHEN TG_OP='DELETE' THEN "model_15273b88e4204687"."delete_token"(OLD.id,OLD.version) ELSE NEW.version END;
SELECT * INTO c FROM "model_15273b88e4204687"."candidates" WHERE version=v;
IF NOT FOUND OR c.action<>TG_OP OR c.key IS DISTINCT FROM (CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END) OR c.image IS DISTINCT FROM (CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('balance',NEW.balance::text,'active',NEW.active,'region',NEW.region) END) THEN RAISE EXCEPTION 'actual effect mismatch'; END IF;
IF TG_OP='INSERT' AND c.old_present THEN RAISE EXCEPTION 'insert presence mismatch'; END IF;
UPDATE "model_15273b88e4204687"."state" SET version=v,present=(TG_OP<>'DELETE') WHERE key=c.key AND version IS NOT DISTINCT FROM c.predecessor AND present=c.old_present;
GET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'effect state mismatch'; END IF;
INSERT INTO "model_15273b88e4204687"."effects" SELECT * FROM "model_15273b88e4204687"."candidates" WHERE version=v;
IF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
END$model$

